'use strict';
window.TypingPractice=(()=>{
 let session=null;
 const normalize=s=>s.normalize('NFKC').toLowerCase().replace(/[\s\p{P}\p{S}]/gu,'');
 function matches(w,input){return (w.hanjaReading?[w.hanjaReading]:[w.korean,...w.forms]).flatMap(s=>s.split(' / ')).some(s=>normalize(s)===normalize(input))}
 function reset(){session=null}
 function render(){const box=$('#studyContent');if(!session){const pool=filtered();if(!pool.length){box.innerHTML=empty();return}session={cards:shuffle(pool),at:0,checked:false,correct:0}}if(session.at>=session.cards.length){box.innerHTML=`<div class="result"><div class="eyebrow">TYPING PRACTICE COMPLETE</div><h2>${session.correct}/${session.cards.length} recalled ♡</h2><p>Every attempt makes the next recall easier.</p><button class="btn primary" id="restartTyping">Try again</button></div>`;$('#restartTyping').onclick=()=>{reset();render()};return}const w=session.cards[session.at];box.innerHTML=`<article class="typing-card"><div class="eyebrow">${w.hanjaReading?'READ THE HANJA':'TYPE THE KOREAN'} · ${session.at+1}/${session.cards.length}</div><h3>${e(w.hanjaReading?w.korean:w.quizAnswer)}</h3><form id="typingForm"><label for="typedKorean">${w.hanjaReading?'Type the Korean reading (e.g. 국)':'Can you remember it in Korean?'}</label><input id="typedKorean" lang="ko" placeholder="한국어로 입력하세요" autocomplete="off" ${session.checked?'disabled':''}><button class="btn primary" ${session.checked?'disabled':''}>Check answer</button></form><div id="typingFeedback" role="status"></div><button class="text-link" id="showTypingAnswer" ${session.checked?'hidden':''}>I don’t know · reveal answer</button><button class="btn primary" id="nextTyped" ${session.checked?'':'hidden'}>Next word →</button></article>`;const check=reveal=>{if(session.checked)return;const input=$('#typedKorean').value.trim();if(!reveal&&!input)return;session.checked=true;const correct=!reveal&&matches(w,input);if(correct)session.correct++;window.StudyHub.schedule(w,correct);record(w);if(!correct)mistake(w);$('#typingFeedback').innerHTML=`<strong>${correct?'✓ Correct!':'↺ Keep this one for another review.'}</strong><p lang="ko">${e(w.hanjaReading?w.answer:w.korean)}</p>${!correct&&input?`<small>You typed: ${e(input)}</small>`:''}`;$('#typedKorean').disabled=true;$('#typingForm').querySelector('button').disabled=true;$('#showTypingAnswer').hidden=true;$('#nextTyped').hidden=false;$('#nextTyped').focus()};$('#typingForm').onsubmit=ev=>{ev.preventDefault();if(!ev.isComposing)check(false)};$('#showTypingAnswer').onclick=()=>check(true);$('#nextTyped').onclick=()=>{session.at++;session.checked=false;render()};$('#typedKorean').focus()}
 return{render,reset,matches,normalize};
})();
